import json,sys
W=sys.argv[1]
t=json.load(open(W+'/taxonomy.json'))
for i in range(19,27):
    p=f'{W}/verified/Q{i}.json'
    raw=open(p,encoding='utf-8').read()
    d=json.loads(raw)
    bad=[]
    if '—' in raw: bad.append('emdash')
    if '–' in raw: bad.append('endash')
    if d.get('studyDesign') and d['studyDesign'] not in t['studyDesigns']: bad.append('design')
    for k,tk in [('domains','domains'),('audiences','audiences'),('sports','sports'),('populations','populations')]:
        for v in d.get(k) or []:
            if v not in t[tk]: bad.append(k+':'+v)
    if d.get('primaryDomain') and d['primaryDomain'] not in (d.get('domains') or []): bad.append('primary')
    v=d['verification']
    print(d['id'],d['decision'],v['status'],len(v['changes']),v['spotCheckPriority'],bad)
EOF

